/// Double-line vertical scrollbar symbols
pub const DOUBLE_VERTICAL: Set = Set {
    track: "║",
    thumb: "█",
    begin: "▲",
    end: "▼",
};

/// Double-line horizontal scrollbar symbols
pub const DOUBLE_HORIZONTAL: Set = Set {
    track: "═",
